<?php
require_once __DIR__.'/load_env.php';
function db_url(): string { $u=getenv('DATABASE_URL'); if(!$u) throw new RuntimeException('DATABASE_URL não configurada.'); return trim($u); }
function db_parts(): array {$p=parse_url(db_url());if($p===false||empty($p['host'])||empty($p['user'])||empty($p['path']))throw new RuntimeException('DATABASE_URL inválida.');parse_str($p['query']??'',$q);$host=$p['host'];$endpoint=explode('.',$host)[0];return ['host'=>$host,'port'=>$p['port']??5432,'user'=>urldecode($p['user']),'pass'=>urldecode($p['pass']??''),'db'=>ltrim($p['path'],'/'),'sslmode'=>$q['sslmode']??'require','endpoint'=>$endpoint];}
function pdo_make(string $dsn,string $u,string $p):PDO{return new PDO($dsn,$u,$p,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);}
function db():PDO{static $pdo=null;if($pdo)return $pdo;$c=db_parts();$base="pgsql:host={$c['host']};port={$c['port']};dbname={$c['db']};sslmode={$c['sslmode']}";try{$pdo=pdo_make($base.";options=endpoint={$c['endpoint']}",$c['user'],$c['pass']);}catch(PDOException $e){if(str_contains($c['host'],'.neon.tech')&&stripos($e->getMessage(),'Endpoint ID is not specified')!==false){$pdo=pdo_make($base,$c['user'],'endpoint='.$c['endpoint'].'$'.$c['pass']);}else throw $e;}return $pdo;}
